static unsigned injections=0,blocked_terminal=0,discarded_terminal=0,abort_terminal=0,control_conflicts=0,done_conflicts=0;
static void hard_reset(){d.cmd=0;d.cfg=0;d.ack=0;d.soft_abort=0;hold_external=false;d.reset=1;step();d.reset=0;step();need(d.epoch==0&&!d.busy&&!d.done&&fifo.empty(),"coordinated reset");}
static void inject_epoch(uint32_t v){need(!d.busy&&fifo.empty(),"injection only idle with empty fabric");d.epoch=v;d.eval();need(d.epoch==v,"actual exposed epoch injection readback");step();need(d.epoch==v,"actual epoch holds through edge");injections++;}
static void reject_commands(){d.cmd=1;for(int k=0;k<12;k++){need(!step().command&&d.epoch==0xffffffffu&&!d.cmd_ready&&!d.busy&&!d.done&&!d.ext_req,"terminal command rejection");blocked_terminal++;}d.cmd=0;}
static void response(uint32_t tag){need(fifo.empty(),"empty finite fabric");auto stale=d.stale_responses;fifo.push_back({tag,0,{0xffffffffu,0x12345678,0xa5a5a5a5,0}});step();need(fifo.empty()&&d.stale_responses==stale+1,"terminal idle response discarded");need(!d.done&&!d.busy&&!d.ext_req&&d.epoch==0xffffffffu,"terminal response no ghost");discarded_terminal++;}
static void terminal_abort(const Case& c,bool same_edge){hard_reset();prepare(c,1);cfg(true,400,{0xa5a5a5a5,0xa5a5a5a5,0xa5a5a5a5,0xa5a5a5a5});inject_epoch(0xfffffffeu);hold_external=true;start();auto begin=ticks;while(fifo.empty()){step();need(ticks-begin<100,"final active request");}while(fifo.front().delay)step();need(d.epoch==0xffffffffu&&d.busy,"active final epoch");auto stale=d.stale_responses;d.cmd=1;d.soft_abort=1;if(same_edge)hold_external=false;auto event=step();need(!event.command,"terminal abort command priority");d.soft_abort=0;d.cmd=0;hold_external=false;if(!same_edge)step();need(fifo.empty()&&d.stale_responses==stale+1,"terminal aborted matching response discarded");need(d.epoch==0xffffffffu&&!d.busy&&!d.done,"terminal abort saturation");for(int i=0;i<20;i++){step();need(!d.done&&!d.ext_req,"no terminal stale completion");}need(cfg(false,400)[0]==0xa5a5a5a5,"terminal abort SRAM retained");abort_terminal++;discarded_terminal++;reject_commands();}
static void reset_signal(bool hard,bool value){d.reset=hard&&value;d.soft_abort=!hard&&value;}
static void control_priority(){for(bool hard:{false,true}){
 hard_reset();cfg(true,400,{0xa5a5a5a5,0,0,0});d.cfg=1;d.cfg_wr=1;d.cfg_addr=400;d.cfg_take=1;d.cfg_din[0]=0xdeadbeef;reset_signal(hard,true);d.eval();need(!d.cfg_ready&&!d.cfg_valid&&!d.done,"reset masks idle config outputs");auto e=step();need(!e.cfg_req&&!e.cfg_rsp&&!e.command,"reset cancels idle cfg handshake");d.cfg=0;reset_signal(hard,false);step();need(cfg(false,400)[0]==0xa5a5a5a5,"cancelled cfg never writes SRAM");control_conflicts++;
 d.cfg=1;d.cfg_wr=0;d.cfg_take=0;need(step().cfg_req,"pending cfg accepted before reset");d.cfg=0;step();need(d.cfg_valid,"pending cfg response held");reset_signal(hard,true);d.cfg_take=1;d.eval();need(!d.cfg_valid&&!d.cfg_ready&&!d.done,"reset masks pending cfg response");e=step();need(!e.cfg_req&&!e.cfg_rsp&&!e.command,"pending response cancelled at reset");reset_signal(hard,false);for(int j=0;j<3;j++)need(!step().cfg_rsp&&!d.cfg_valid,"no ghost cancelled cfg response");need(cfg(false,400)[0]==0xa5a5a5a5,"config works after reset cancellation");control_conflicts++;
}}
static void done_priority(const Case& c){hard_reset();prepare(c,1);inject_epoch(0xfffffffeu);start();wait_done();need(d.done&&d.status==0,"actual complete result awaiting ack");d.ack=1;d.soft_abort=1;d.eval();need(!d.done,"abort masks held completion before accepting ack");auto e=step();need(!e.command&&!e.cfg_rsp,"abort cannot publish another handshake");d.ack=0;d.soft_abort=0;step();need(!d.busy&&!d.done&&d.epoch==0xffffffffu&&!d.cmd_ready,"done abort priority and epoch saturation");done_conflicts++;}
int main(int argc,char**argv){try{Verilated::commandArgs(argc,argv);need(argc==4,"vectors output stall");stall=std::stoi(argv[3]);hard_reset();std::ifstream in(argv[1]);out.open(argv[2]);need(bool(in)&&bool(out),"files");Case c;need(bool(in>>c.name>>c.p0>>c.p1>>c.g>>c.coefficient),"actual first complete case");
 prepare(c,0);inject_epoch(0xfffffffdu);auto e=d.epoch;d.soft_abort=1;step();d.soft_abort=0;need(d.epoch==e+1&&d.epoch==0xfffffffeu,"penultimate abort increments without wrap");start();need(d.epoch==0xffffffffu,"last accepted command reaches max");finish(c,0,"last-legal-max");reject_commands();response(0xffffffffu);response(0xfffffffeu);response(0);reject_commands();
 terminal_abort(c,false);terminal_abort(c,true);control_priority();done_priority(c);hard_reset();prepare(c,1);start();need(d.epoch==1,"post-coordinated-reset command");finish(c,1,"after-terminal-reset");
 std::ofstream p(std::string(argv[2])+".boundary.json");p<<"{\"schema\":\"epoch92-boundary-v1\",\"injections\":"<<injections<<",\"blocked_terminal_edges\":"<<blocked_terminal<<",\"discarded_terminal_responses\":"<<discarded_terminal<<",\"terminal_aborts\":"<<abort_terminal<<",\"control_reset_conflicts\":"<<control_conflicts<<",\"done_abort_conflicts\":"<<done_conflicts<<",\"full_commands\":2,\"final_epoch\":"<<d.epoch<<",\"no_wrap\":true,\"final_active_reply_preserved\":true,\"coordinated_reset_restart\":true}\n";std::cout<<"PASS_ACTUAL_RTL_EPOCH_BOUNDARIES\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<" epoch="<<d.epoch<<" state="<<unsigned(d.debug_state)<<"\n";return 1;}}
